using Microsoft.VisualStudio.TestTools.UnitTesting;
using Payments;

namespace Payments.Tests;

[TestClass]
public class PaymentGatewayChargeTests
{
    private PaymentGateway _gateway = null!;

    [TestInitialize]
    public void Setup()
    {
        _gateway = new PaymentGateway();
    }

    [TestMethod]
    public async Task ChargeAsync_ValidCardAndAmount_ReturnsSuccessWithChargeId()
    {
        var result = await _gateway.ChargeAsync("tok_valid_visa", 49.99m);

        Assert.IsTrue(result.Success);
        Assert.IsFalse(string.IsNullOrEmpty(result.ChargeId));
    }

    [TestMethod]
    public async Task ChargeAsync_ZeroAmount_ReturnsFailure()
    {
        var result = await _gateway.ChargeAsync("tok_valid_visa", 0m);

        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    public async Task ChargeAsync_NegativeAmount_ReturnsFailure()
    {
        var result = await _gateway.ChargeAsync("tok_valid_visa", -10.00m);

        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentNullException))]
    public async Task ChargeAsync_NullCardToken_ThrowsArgumentNullException()
    {
        await _gateway.ChargeAsync(null!, 25.00m);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentException))]
    public async Task ChargeAsync_EmptyCardToken_ThrowsArgumentException()
    {
        await _gateway.ChargeAsync("", 25.00m);
    }

    [TestMethod]
    public async Task ChargeAsync_DeclinedCard_ReturnsFailure()
    {
        var result = await _gateway.ChargeAsync("tok_declined", 50.00m);

        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    public async Task ChargeAsync_LargeAmount_ReturnsSuccess()
    {
        var result = await _gateway.ChargeAsync("tok_valid_visa", 9999.99m);

        Assert.IsTrue(result.Success);
        Assert.IsFalse(string.IsNullOrEmpty(result.ChargeId));
    }

    [TestMethod]
    public async Task ChargeAsync_MinimumAmount_ReturnsSuccess()
    {
        var result = await _gateway.ChargeAsync("tok_valid_visa", 0.01m);

        Assert.IsTrue(result.Success);
    }
}

[TestClass]
public class PaymentGatewayRefundTests
{
    private PaymentGateway _gateway = null!;

    [TestInitialize]
    public void Setup()
    {
        _gateway = new PaymentGateway();
    }

    [TestMethod]
    public async Task RefundAsync_ValidChargeId_ReturnsSuccessWithRefundId()
    {
        var result = await _gateway.RefundAsync("ch_valid_123");

        Assert.IsTrue(result.Success);
        Assert.IsFalse(string.IsNullOrEmpty(result.RefundId));
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentNullException))]
    public async Task RefundAsync_NullChargeId_ThrowsArgumentNullException()
    {
        await _gateway.RefundAsync(null!);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentException))]
    public async Task RefundAsync_EmptyChargeId_ThrowsArgumentException()
    {
        await _gateway.RefundAsync("");
    }

    [TestMethod]
    public async Task RefundAsync_NonExistentChargeId_ReturnsFailure()
    {
        var result = await _gateway.RefundAsync("ch_nonexistent_999");

        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    public async Task RefundAsync_AlreadyRefundedCharge_ReturnsFailure()
    {
        var result = await _gateway.RefundAsync("ch_already_refunded");

        Assert.IsFalse(result.Success);
    }
}

[TestClass]
public class PaymentGatewayWebhookTests
{
    private PaymentGateway _gateway = null!;

    [TestInitialize]
    public void Setup()
    {
        _gateway = new PaymentGateway();
    }

    [TestMethod]
    public async Task ProcessWebhookAsync_ValidPayloadAndSignature_ReturnsVerified()
    {
        var payload = """{"event":"charge.succeeded","chargeId":"ch_123"}""";
        var signature = "valid_sig_abc";

        var result = await _gateway.ProcessWebhookAsync(payload, signature);

        Assert.IsTrue(result.Verified);
        Assert.AreEqual("charge.succeeded", result.EventType);
    }

    [TestMethod]
    public async Task ProcessWebhookAsync_InvalidSignature_ReturnsNotVerified()
    {
        var payload = """{"event":"charge.succeeded","chargeId":"ch_123"}""";
        var signature = "invalid_signature";

        var result = await _gateway.ProcessWebhookAsync(payload, signature);

        Assert.IsFalse(result.Verified);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentNullException))]
    public async Task ProcessWebhookAsync_NullPayload_ThrowsArgumentNullException()
    {
        await _gateway.ProcessWebhookAsync(null!, "some_sig");
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentNullException))]
    public async Task ProcessWebhookAsync_NullSignature_ThrowsArgumentNullException()
    {
        await _gateway.ProcessWebhookAsync("""{"event":"test"}""", null!);
    }

    [TestMethod]
    public async Task ProcessWebhookAsync_EmptyPayload_ReturnsNotVerified()
    {
        var result = await _gateway.ProcessWebhookAsync("", "some_sig");

        Assert.IsFalse(result.Verified);
    }

    [TestMethod]
    public async Task ProcessWebhookAsync_RefundEvent_ReturnsCorrectEventType()
    {
        var payload = """{"event":"refund.created","refundId":"re_456"}""";
        var signature = "valid_sig_def";

        var result = await _gateway.ProcessWebhookAsync(payload, signature);

        Assert.IsTrue(result.Verified);
        Assert.AreEqual("refund.created", result.EventType);
    }

    [TestMethod]
    public async Task ProcessWebhookAsync_MalformedJson_ReturnsNotVerified()
    {
        var payload = "not valid json {{{";
        var signature = "some_sig";

        var result = await _gateway.ProcessWebhookAsync(payload, signature);

        Assert.IsFalse(result.Verified);
    }
}

